function findPrimePairs(n) {
  const composite = new Uint8Array(n + 1);
  composite[0] = 1;
  composite[1] = 1;
  for (let p = 2; p * p <= n; p++) {
    if (composite[p]) {
      continue;
    }
    for (let multiple = p * p; multiple <= n; multiple += p) {
      composite[multiple] = 1;
    }
  }
  const pairs = [];
  for (let x = 2; x <= n - x; x++) {
    const y = n - x;
    if (!composite[x] && !composite[y]) {
      pairs.push([x, y]);
    }
  }
  return pairs;
}

