function findPrimePairs(n) {
  const isPrime = (v) => {
    if (v < 2) return false;
    for (let d = 2; d * d <= v; d++) if (v % d === 0) return false;
    return true;
  };
  const result = [];
  for (let x = 1; x <= n; x++)
    for (let y = x; y <= n; y++)
      if (x + y === n && isPrime(x) && isPrime(y)) result.push([x, y]);
  return result;
}

